const daysPerMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const prefixSum = Array(12).fill(0);

for (let i = 1; i < 12; i++) {
    prefixSum[i] = prefixSum[i - 1] + daysPerMonth[i - 1];
}

const convert = (date) => {
    const [month, day] = date.split('-');

    return prefixSum[Number(month) - 1] + Number(day);
};

/**
 * @param {string} arriveAlice
 * @param {string} leaveAlice
 * @param {string} arriveBob
 * @param {string} leaveBob
 * @return {number}
 */
var countDaysTogether = function(arriveAlice, leaveAlice, arriveBob, leaveBob) {
    if (leaveAlice < arriveBob || leaveBob < arriveAlice) return 0;

    const s1 = convert(arriveAlice);
    const e1 = convert(leaveAlice);
    const s2 = convert(arriveBob);
    const e2 = convert(leaveBob);

    return Math.min(e1, e2) - Math.max(s1, s2) + 1;
};
